add('SP-STOCK','Exact token-accounting law','EXACT_CONDITIONAL','S=active stock + unspent bank','Renewal preserves S and inspection consumes exactly |omega+|. This counts prepared tokens, not joules or chain support.','§5','Renewal preserves S',[proof('SP-DRIVE','Defines inspection consumption.'),proof('SP-BANK','Defines transfer from unspent bank to active stock.')])
add('SP-TERM','Strict potential and finite termination','EXACT_CONDITIONAL','V=4S+2|q|+|L_cache|+(B−k)','Every committed tick strictly reduces the integer potential for either frozen branch. The episode reaches a full model fixed point within V_initial changes.','§5','Every committed tick strictly decreases V',[proof('SP-STOCK','Accounts for stock across inspection and renewal.'),choice('SP-CLOSE','Supplies the close response branch.'),choice('SP-HOLD','Supplies the alternative hold branch.'),choice('SP-STOP','Defines committed changes and the full terminal test.')])
